USE [JamunaBankProcurement];
GO
CREATE OR ALTER PROCEDURE dbo.usp_ProcurementDashboard_Get
 @Year INT
AS
BEGIN
 SET NOCOUNT ON;
 IF @Year NOT BETWEEN 2000 AND 2100 THROW 51000,'Dashboard year is invalid.',1;

 DECLARE @FromDate DATE=DATEFROMPARTS(@Year,1,1),@ToDate DATE=DATEFROMPARTS(@Year+1,1,1);

 SELECT h.REQUISITION_ID,
        COALESCE(w.CURRENT_STAGE,CASE a.ASSIGNMENT_TYPE
          WHEN 'MANAGER' THEN 'BRANCH_MANAGER'
          WHEN 'PROCUREMENT_OFFICER_POOL' THEN 'PROCUREMENT_OFFICER'
          WHEN 'PROCUREMENT_OFFICER' THEN 'PROCUREMENT_OFFICER'
          WHEN 'PROCUREMENT_AUTHORITY_POOL' THEN 'PROCUREMENT_AUTHORITY'
          WHEN 'CONCERN_OFFICIAL' THEN 'CONCERN_DIVISION'
          WHEN 'CONCERN_AUTHORITY' THEN 'CONCERN_AUTHORITY' END) CURRENT_STAGE
 INTO #Pending
 FROM dbo.REQUISITION_HEADER h
 OUTER APPLY(SELECT TOP(1)wi.CURRENT_STAGE FROM dbo.WORKFLOW_INSTANCE wi WHERE wi.REQUISITION_ID=h.REQUISITION_ID AND wi.COMPLETED_DATE IS NULL AND wi.CURRENT_STATUS IN('PENDING','TAKEN') ORDER BY wi.WORKFLOW_INSTANCE_ID DESC)w
 OUTER APPLY(SELECT TOP(1)ra.ASSIGNMENT_TYPE FROM dbo.REQUISITION_ASSIGNMENT ra WHERE ra.REQUISITION_ID=h.REQUISITION_ID AND ra.IS_CURRENT=1 ORDER BY ra.ASSIGNMENT_ID DESC)a
 WHERE h.IS_ACTIVE=1
   AND h.CURRENT_STATUS IN('SUBMITTED','IN_WORKFLOW','RETURNED')
   AND NOT EXISTS(SELECT 1 FROM dbo.PROCUREMENT_TRACKING pt WHERE pt.REQUISITION_ID=h.REQUISITION_ID);

 SELECT (SELECT COUNT(*) FROM #Pending) PENDING_REQUISITIONS,
        (SELECT COUNT(*) FROM dbo.PROCUREMENT_TRACKING p JOIN dbo.PROCUREMENT_STATUS_MASTER s ON s.STATUS_ID=p.CURRENT_STATUS_ID WHERE s.STATUS_CODE='READY_FOR_PROCUREMENT') READY_FOR_PROCUREMENT,
        (SELECT COUNT(*) FROM dbo.PROCUREMENT_TRACKING p JOIN dbo.PROCUREMENT_STATUS_MASTER s ON s.STATUS_ID=p.CURRENT_STATUS_ID WHERE s.STATUS_CODE NOT IN('READY_FOR_PROCUREMENT','PROCUREMENT_COMPLETED')) UNDER_PROCUREMENT,
        (SELECT COUNT(DISTINCT p.REQUISITION_ID) FROM dbo.PROCUREMENT_TRACKING p JOIN dbo.PROCUREMENT_STATUS_HISTORY ph ON ph.PROCUREMENT_ID=p.PROCUREMENT_ID JOIN dbo.PROCUREMENT_STATUS_MASTER s ON s.STATUS_ID=ph.STATUS_ID WHERE s.STATUS_CODE='PROCUREMENT_COMPLETED' AND ph.STATUS_DATE>=@FromDate AND ph.STATUS_DATE<@ToDate) PROCUREMENT_COMPLETED,
        @Year SELECTED_YEAR;

 SELECT p.CURRENT_STAGE STAGE_CODE,CASE p.CURRENT_STAGE
   WHEN 'MANAGER' THEN 'Branch/Division Manager' WHEN 'BRANCH_MANAGER' THEN 'Branch/Division Manager'
   WHEN 'PROCUREMENT_OFFICER' THEN 'Procurement Officer'
   WHEN 'PROCUREMENT_AUTHORITY' THEN 'Procurement Authority'
   WHEN 'CONCERN_DIVISION' THEN 'Concern Division Official'
   WHEN 'CONCERN_AUTHORITY' THEN 'Concern Division Authority'
   WHEN 'PROCUREMENT_AUTHORITY_FINAL' THEN 'Procurement Authority (Final Approval)'
   ELSE REPLACE(COALESCE(p.CURRENT_STAGE,'UNASSIGNED'),'_',' ') END STAGE_NAME,COUNT(*) STAGE_COUNT
 FROM #Pending p GROUP BY p.CURRENT_STAGE ORDER BY MIN(CASE p.CURRENT_STAGE WHEN 'MANAGER' THEN 1 WHEN 'BRANCH_MANAGER' THEN 1 WHEN 'PROCUREMENT_OFFICER' THEN 2 WHEN 'PROCUREMENT_AUTHORITY' THEN 3 WHEN 'CONCERN_DIVISION' THEN 4 WHEN 'CONCERN_AUTHORITY' THEN 5 WHEN 'PROCUREMENT_AUTHORITY_FINAL' THEN 6 ELSE 99 END);

 ;WITH m AS(SELECT 1 MONTH_NO UNION ALL SELECT MONTH_NO+1 FROM m WHERE MONTH_NO<12),
 received AS(SELECT MONTH(REQUESTED_DATE)MONTH_NO,COUNT(*) CNT FROM dbo.REQUISITION_HEADER WHERE REQUESTED_DATE>=@FromDate AND REQUESTED_DATE<@ToDate GROUP BY MONTH(REQUESTED_DATE)),
 completed AS(SELECT MONTH(ph.STATUS_DATE)MONTH_NO,COUNT(DISTINCT p.REQUISITION_ID)CNT FROM dbo.PROCUREMENT_STATUS_HISTORY ph JOIN dbo.PROCUREMENT_TRACKING p ON p.PROCUREMENT_ID=ph.PROCUREMENT_ID JOIN dbo.PROCUREMENT_STATUS_MASTER s ON s.STATUS_ID=ph.STATUS_ID WHERE s.STATUS_CODE='PROCUREMENT_COMPLETED' AND ph.STATUS_DATE>=@FromDate AND ph.STATUS_DATE<@ToDate GROUP BY MONTH(ph.STATUS_DATE))
 SELECT m.MONTH_NO,LEFT(DATENAME(MONTH,DATEFROMPARTS(@Year,m.MONTH_NO,1)),3)MONTH_NAME,COALESCE(r.CNT,0)RECEIVED_COUNT,COALESCE(c.CNT,0)COMPLETED_COUNT FROM m LEFT JOIN received r ON r.MONTH_NO=m.MONTH_NO LEFT JOIN completed c ON c.MONTH_NO=m.MONTH_NO ORDER BY m.MONTH_NO OPTION(MAXRECURSION 12);

 ;WITH ready AS(SELECT p.PROCUREMENT_ID,p.REQUISITION_ID,MIN(ph.STATUS_DATE)READY_DATE FROM dbo.PROCUREMENT_TRACKING p JOIN dbo.PROCUREMENT_STATUS_HISTORY ph ON ph.PROCUREMENT_ID=p.PROCUREMENT_ID JOIN dbo.PROCUREMENT_STATUS_MASTER hs ON hs.STATUS_ID=ph.STATUS_ID AND hs.STATUS_CODE='READY_FOR_PROCUREMENT' JOIN dbo.PROCUREMENT_STATUS_MASTER cs ON cs.STATUS_ID=p.CURRENT_STATUS_ID AND cs.STATUS_CODE='READY_FOR_PROCUREMENT' GROUP BY p.PROCUREMENT_ID,p.REQUISITION_ID)
 SELECT TOP(5)h.REQUISITION_ID,h.REQUISITION_NO,STRING_AGG(CONVERT(NVARCHAR(MAX),i.ITEM_NAME_SNAPSHOT),', ')ASSET_NAME,o.ORG_UNIT_NAME REQUESTING_UNIT,STRING_AGG(CONVERT(NVARCHAR(MAX),REPLACE(i.REQ_TYPE,'_',' ')),', ') REQUISITION_TYPE,r.READY_DATE,DATEDIFF(DAY,r.READY_DATE,SYSUTCDATETIME()) READY_SINCE_DAYS
 FROM ready r JOIN dbo.REQUISITION_HEADER h ON h.REQUISITION_ID=r.REQUISITION_ID JOIN dbo.ORG_UNIT o ON o.ORG_UNIT_ID=h.REQUESTED_ORG_UNIT_ID JOIN dbo.REQUISITION_ITEM i ON i.REQUISITION_ID=h.REQUISITION_ID AND i.IS_ACTIVE=1
 GROUP BY h.REQUISITION_ID,h.REQUISITION_NO,o.ORG_UNIT_NAME,r.READY_DATE ORDER BY r.READY_DATE DESC;

 ;WITH categoryCounts AS(SELECT c.ASSET_CATEGORY_ID,c.CATEGORY_NAME,COUNT(DISTINCT h.REQUISITION_ID)CATEGORY_COUNT FROM dbo.ASSET_CATEGORY c LEFT JOIN dbo.ASSET_MASTER am ON am.ASSET_CATEGORY_ID=c.ASSET_CATEGORY_ID LEFT JOIN dbo.REQUISITION_ITEM i ON i.ASSET_ID=am.ASSET_ID AND i.IS_ACTIVE=1 LEFT JOIN dbo.REQUISITION_HEADER h ON h.REQUISITION_ID=i.REQUISITION_ID AND h.REQUESTED_DATE>=@FromDate AND h.REQUESTED_DATE<@ToDate WHERE c.IS_ACTIVE=1 GROUP BY c.ASSET_CATEGORY_ID,c.CATEGORY_NAME), totals AS(SELECT SUM(CATEGORY_COUNT)TOTAL_COUNT FROM categoryCounts)
 SELECT c.ASSET_CATEGORY_ID,c.CATEGORY_NAME,c.CATEGORY_COUNT,CAST(CASE WHEN t.TOTAL_COUNT=0 THEN 0 ELSE c.CATEGORY_COUNT*100.0/t.TOTAL_COUNT END AS DECIMAL(6,2))PERCENTAGE FROM categoryCounts c CROSS JOIN totals t ORDER BY c.CATEGORY_COUNT DESC,c.CATEGORY_NAME;
END;
GO
